/// The string a `Kind` is stored as on either backend.
fn kind_stored(value: &crate::schema::Kind) -> &'static str {
    match value {
        crate::schema::Kind::Gamma => "gamma",
        crate::schema::Kind::Alpha => "alpha",
        crate::schema::Kind::Beta => "beta",
        crate::schema::Kind::Zeta => "delta",
        // A `#[serde(skip)]` variant is never stored.
        #[allow(unreachable_patterns)]
        _ => "",
    }
}

impl Store {
    pub async fn list_items(
        &self,
        order: &[OrderBy<ItemSortField>],
        limit: Option<u64>,
        offset: Option<u64>,
    ) -> Result<Vec<Item>, AppError> {
        let mut query = order_items_query(item::Entity::find(), order);
        let limit = limit.map(|l| l.min(i64::MAX as u64));
        let offset = offset.map(|o| o.min(i64::MAX as u64));
        // sqlite-only: SQLite rejects OFFSET without LIMIT, so an offset alone takes i64::MAX rows.
        if let Some(l) = limit.or(offset.map(|_| i64::MAX as u64)) {
            query = query.limit(l);
        }
        if let Some(o) = offset {
            query = query.offset(o);
        }
        let models = query.all(self.db()).await.map_err(|e| AppError::DbError(e.to_string()))?;

        let mut entities: Vec<Item> = models.iter().map(Item::from_model).collect::<Result<_, _>>()?;
        for entity in &mut entities {
            self.populate_item_relations(entity).await?;
        }
        Ok(entities)
    }

    pub async fn count_items(&self) -> Result<u64, AppError> {
        item::Entity::find().count(self.db()).await.map_err(|e| AppError::DbError(e.to_string()))
    }

    pub async fn get_item(&self, id: &str) -> Result<Item, AppError> {
        let model = item::Entity::find_by_id(id)
            .one(self.db())
            .await
            .map_err(|e| AppError::DbError(e.to_string()))?
            .ok_or_else(|| AppError::ItemNotFound(id.to_string()))?;

        let mut entity = Item::from_model(&model)?;
        self.populate_item_relations(&mut entity).await?;
        Ok(entity)
    }

    pub async fn create_item(&self, mut item: Item) -> Result<Item, AppError> {
        hooks::before_create(self, &mut item).await?;

        let tags = item.tags.clone();
        let children = item.children.clone();

        if !item.id.trim().is_empty() && item.children.contains(&item.id) {
            return Err(AppError::ItemParentCycle(item.id.clone()));
        }

        for child_id in &item.children {
            if !self.item_exists(child_id).await? {
                return Err(AppError::ItemNotFound(child_id.clone()));
            }
        }
        for target_id in &item.tags {
            if !self.tag_exists(target_id).await? {
                return Err(AppError::TagNotFound(target_id.clone()));
            }
        }

        if let Some(v) = Some(item.n_u64).filter(|v| i64::try_from(*v).is_err()) {
            return Err(AppError::DbError(format!("Item.n_u64: value {v} is out of range for i64")));
        }
        if let Some(v) = Some(item.n_usize).filter(|v| i64::try_from(*v).is_err()) {
            return Err(AppError::DbError(format!("Item.n_usize: value {v} is out of range for i64")));
        }
        if let Some(v) = Some(item.n_u128).filter(|v| i64::try_from(*v).is_err()) {
            return Err(AppError::DbError(format!("Item.n_u128: value {v} is out of range for i64")));
        }
        if let Some(v) = Some(item.n_isize).filter(|v| i64::try_from(*v).is_err()) {
            return Err(AppError::DbError(format!("Item.n_isize: value {v} is out of range for i64")));
        }
        if let Some(v) = Some(item.n_i128).filter(|v| i64::try_from(*v).is_err()) {
            return Err(AppError::DbError(format!("Item.n_i128: value {v} is out of range for i64")));
        }
        if let Some(v) = item.maybe_u64.filter(|v| i64::try_from(*v).is_err()) {
            return Err(AppError::DbError(format!("Item.maybe_u64: value {v} is out of range for i64")));
        }

        if item.float32.is_nan() {
            return Err(AppError::DbError("Item.float32: NaN cannot be stored".to_string()));
        }
        if item.float64.is_nan() {
            return Err(AppError::DbError("Item.float64: NaN cannot be stored".to_string()));
        }
        if item.maybe_float32.is_some_and(f32::is_nan) {
            return Err(AppError::DbError("Item.maybe_float32: NaN cannot be stored".to_string()));
        }
        if item.maybe_float64.is_some_and(f64::is_nan) {
            return Err(AppError::DbError("Item.maybe_float64: NaN cannot be stored".to_string()));
        }

        let txn = self.db().begin().await.map_err(|e| AppError::DbError(e.to_string()))?;
        let id = if item.id.trim().is_empty() {
            let base = ontogen_core::id::slugify(&item.title);
            if base.is_empty() {
                return Err(AppError::ItemIdRequired("field \"title\" produced an empty slug".to_string()));
            }
            for candidate in ontogen_core::id::candidates(&base) {
                let taken = item::Entity::find_by_id(candidate.as_str())
                    .one(&txn)
                    .await
                    .map_err(|e| AppError::DbError(e.to_string()))?
                    .is_some();
                if taken {
                    continue;
                }
                item.id = candidate;
                if self.try_insert_item(&txn, &item).await? {
                    break;
                }
            }
            item.id.clone()
        } else {
            ontogen_core::id::validate_id(&item.id).map_err(|e| AppError::DbError(e.to_string()))?;
            if !self.try_insert_item(&txn, &item).await? {
                return Err(AppError::ItemAlreadyExists(item.id));
            }
            item.id.clone()
        };

        self.sync_junction(&txn, "item_tags", "item_id", "tag_id", &id, &tags).await?;
        for child_id in &children {
            self.set_item_parent(&txn, child_id, Some(&id)).await?;
        }
        txn.commit().await.map_err(|e| AppError::DbError(e.to_string()))?;

        let created = self.get_item(&id).await?;
        self.emit_change(ChangeOp::Created, EntityKind::Item, id);

        hooks::after_create(self, &created).await?;
        Ok(created)
    }

    pub async fn update_item(&self, id: &str, updates: ItemUpdate) -> Result<Item, AppError> {
        let existing_model = item::Entity::find_by_id(id)
            .one(self.db())
            .await
            .map_err(|e| AppError::DbError(e.to_string()))?
            .ok_or_else(|| AppError::ItemNotFound(id.to_string()))?;

        let mut current = Item::from_model(&existing_model)?;
        self.populate_item_relations(&mut current).await?;

        hooks::before_update(self, &current, &updates).await?;

        let tags_changed = updates.tags.is_some();
        let children_changed = updates.children.is_some();

        if updates.children.as_ref().is_some_and(|ids| ids.iter().any(|c| c == id)) {
            return Err(AppError::ItemParentCycle(id.to_string()));
        }

        for child_id in updates.children.iter().flatten() {
            if !self.item_exists(child_id).await? {
                return Err(AppError::ItemNotFound(child_id.clone()));
            }
        }
        for target_id in updates.tags.iter().flatten() {
            if !self.tag_exists(target_id).await? {
                return Err(AppError::TagNotFound(target_id.clone()));
            }
        }

        let children_dropped: Vec<String> = match &updates.children {
            Some(new_ids) => current.children.iter().filter(|c| !new_ids.contains(c)).cloned().collect(),
            None => Vec::new(),
        };

        if let Some(v) = updates.n_u64.filter(|v| i64::try_from(*v).is_err()) {
            return Err(AppError::DbError(format!("Item.n_u64: value {v} is out of range for i64")));
        }
        if let Some(v) = updates.n_usize.filter(|v| i64::try_from(*v).is_err()) {
            return Err(AppError::DbError(format!("Item.n_usize: value {v} is out of range for i64")));
        }
        if let Some(v) = updates.n_u128.filter(|v| i64::try_from(*v).is_err()) {
            return Err(AppError::DbError(format!("Item.n_u128: value {v} is out of range for i64")));
        }
        if let Some(v) = updates.n_isize.filter(|v| i64::try_from(*v).is_err()) {
            return Err(AppError::DbError(format!("Item.n_isize: value {v} is out of range for i64")));
        }
        if let Some(v) = updates.n_i128.filter(|v| i64::try_from(*v).is_err()) {
            return Err(AppError::DbError(format!("Item.n_i128: value {v} is out of range for i64")));
        }
        if let Some(v) = updates.maybe_u64.flatten().filter(|v| i64::try_from(*v).is_err()) {
            return Err(AppError::DbError(format!("Item.maybe_u64: value {v} is out of range for i64")));
        }

        if updates.float32.is_some_and(f32::is_nan) {
            return Err(AppError::DbError("Item.float32: NaN cannot be stored".to_string()));
        }
        if updates.float64.is_some_and(f64::is_nan) {
            return Err(AppError::DbError("Item.float64: NaN cannot be stored".to_string()));
        }
        if updates.maybe_float32.flatten().is_some_and(f32::is_nan) {
            return Err(AppError::DbError("Item.maybe_float32: NaN cannot be stored".to_string()));
        }
        if updates.maybe_float64.flatten().is_some_and(f64::is_nan) {
            return Err(AppError::DbError("Item.maybe_float64: NaN cannot be stored".to_string()));
        }

        updates.apply(&mut current);
        let active = current.to_active_model()?;

        let txn = self.db().begin().await.map_err(|e| AppError::DbError(e.to_string()))?;
        active.update(&txn).await.map_err(|e| AppError::DbError(e.to_string()))?;
        if tags_changed {
            self.sync_junction(&txn, "item_tags", "item_id", "tag_id", id, &current.tags).await?;
        }
        if children_changed {
            for child_id in &current.children {
                self.set_item_parent(&txn, child_id, Some(id)).await?;
            }
            for child_id in &children_dropped {
                self.set_item_parent(&txn, child_id, None).await?;
            }
        }
        txn.commit().await.map_err(|e| AppError::DbError(e.to_string()))?;

        let result = self.get_item(id).await?;
        self.emit_change(ChangeOp::Updated, EntityKind::Item, id.to_string());

        hooks::after_update(self, &result).await?;
        Ok(result)
    }

    pub async fn delete_item(&self, id: &str) -> Result<(), AppError> {
        hooks::before_delete(self, id).await?;

        let existing = item::Entity::find_by_id(id)
            .one(self.db())
            .await
            .map_err(|e| AppError::DbError(e.to_string()))?
            .ok_or_else(|| AppError::ItemNotFound(id.to_string()))?;

        let active: item::ActiveModel = existing.into();
        active.delete(self.db()).await.map_err(|e| AppError::DbError(e.to_string()))?;

        self.emit_change(ChangeOp::Deleted, EntityKind::Item, id.to_string());

        hooks::after_delete(self, id).await?;
        Ok(())
    }

    pub(crate) async fn populate_item_relations(
        &self,
        item: &mut crate::schema::Item,
    ) -> Result<(), crate::schema::AppError> {
        item.children = {
            use crate::persistence::db::entities::item;
            // sqlite-only: child ids sort in byte order under SQLite's default BINARY collation.
            let children = item::Entity::find()
                .filter(item::Column::ParentId.eq(&item.id))
                .filter(item::Column::Id.ne(&item.id))
                .order_by_asc(item::Column::Id)
                .all(self.db())
                .await
                .map_err(|e| crate::schema::AppError::DbError(e.to_string()))?;
            children.into_iter().map(|m| m.id).collect()
        };
        item.tags = self.load_junction_ids("item_tags", "item_id", "tag_id", &item.id).await?;
        Ok(())
    }

    async fn try_insert_item<C: sea_orm::ConnectionTrait>(&self, conn: &C, item: &Item) -> Result<bool, AppError> {
        let active = item.to_active_model()?;
        match active.insert(conn).await {
            Ok(_) => Ok(true),
            Err(e) if matches!(e.sql_err(), Some(sea_orm::SqlErr::UniqueConstraintViolation(_))) => {
                // sqlite-only: a failed INSERT leaves an SQLite transaction usable; Postgres aborts it.
                let taken = item::Entity::find_by_id(item.id.as_str())
                    .one(conn)
                    .await
                    .map_err(|e| AppError::DbError(e.to_string()))?
                    .is_some();
                if taken { Ok(false) } else { Err(AppError::DbError(e.to_string())) }
            }
            Err(e) => Err(AppError::DbError(e.to_string())),
        }
    }

    async fn set_item_parent<C: sea_orm::ConnectionTrait>(
        &self,
        conn: &C,
        child_id: &str,
        parent_id: Option<&str>,
    ) -> Result<(), AppError> {
        use sea_orm::Value;
        // sqlite-only: raw SQL built for DatabaseBackend::Sqlite, with `?` placeholders.
        let stmt = sea_orm::Statement::from_sql_and_values(
            sea_orm::DatabaseBackend::Sqlite,
            "UPDATE items SET parent_id = ? WHERE id = ?",
            [
                parent_id.map(|p| Value::from(p.to_string())).unwrap_or(Value::String(None)),
                Value::from(child_id.to_string()),
            ],
        );
        conn.execute(stmt).await.map_err(|e| AppError::DbError(e.to_string()))?;
        Ok(())
    }

    pub(crate) async fn item_exists(&self, id: &str) -> Result<bool, AppError> {
        Ok(item::Entity::find_by_id(id).one(self.db()).await.map_err(|e| AppError::DbError(e.to_string()))?.is_some())
    }
}

/// Applies `order` to `query` as `list_items` does: each key with nulls first ascending and last
/// descending, then the id. A hand-written list that filters in SQL orders through this.
pub fn order_items_query(mut query: Select<item::Entity>, order: &[OrderBy<ItemSortField>]) -> Select<item::Entity> {
    for key in ontogen_core::order::effective(order) {
        let column = match key.field {
            ItemSortField::Id => item::Column::Id,
            ItemSortField::Title => item::Column::Title,
            ItemSortField::Int32 => item::Column::Int32,
            ItemSortField::Int64 => item::Column::Int64,
            ItemSortField::Float32 => item::Column::Float32,
            ItemSortField::Float64 => item::Column::Float64,
            ItemSortField::Flag => item::Column::Flag,
            ItemSortField::Kind => item::Column::Kind,
            ItemSortField::MaybeText => item::Column::MaybeText,
            ItemSortField::MaybeInt32 => item::Column::MaybeInt32,
            ItemSortField::MaybeInt64 => item::Column::MaybeInt64,
            ItemSortField::MaybeFloat32 => item::Column::MaybeFloat32,
            ItemSortField::MaybeFloat64 => item::Column::MaybeFloat64,
            ItemSortField::MaybeFlag => item::Column::MaybeFlag,
            ItemSortField::MaybeKind => item::Column::MaybeKind,
            ItemSortField::NU8 => item::Column::NU8,
            ItemSortField::NU16 => item::Column::NU16,
            ItemSortField::NU32 => item::Column::NU32,
            ItemSortField::NU64 => item::Column::NU64,
            ItemSortField::NUsize => item::Column::NUsize,
            ItemSortField::NU128 => item::Column::NU128,
            ItemSortField::NI8 => item::Column::NI8,
            ItemSortField::NI16 => item::Column::NI16,
            ItemSortField::NIsize => item::Column::NIsize,
            ItemSortField::NI128 => item::Column::NI128,
            ItemSortField::MaybeU32 => item::Column::MaybeU32,
            ItemSortField::MaybeU64 => item::Column::MaybeU64,
        };
        let (direction, nulls) = match key.direction {
            ontogen_core::order::Direction::Asc => (Order::Asc, NullOrdering::First),
            ontogen_core::order::Direction::Desc => (Order::Desc, NullOrdering::Last),
        };
        // sqlite-only: string keys sort in byte order under SQLite's default BINARY collation.
        query = query.order_by_with_nulls(column, direction, nulls);
    }
    query
}
